// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface BoundedOptions {
//   concurrency: number;
//   maxQueueDepth: number;
// }
//
// export interface BoundedQueue {
//   submit(url: string): Promise<PageResult>;
//   depth(): number;
//   highWaterMark(): number;
//   rejected(): number;
// }
//
// interface Waiting {
//   url: string;
//   settle(result: PageResult): void;
