// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface PaginateOptions {
//   maxPages: number;
// }
//
// export interface PaginateResult {
//   items: unknown[];
//   pages: number;
//   truncated: boolean;
//   looped: boolean;
// }
//
// interface PageEnvelope {
//   items?: unknown[];
//   next?: string | null;
// }

import { request } from '@lab/net';
export async function fetchAllPages(startUrl, options) {
    const items = [];
    const visited = new Set();
    let cursor = startUrl;
    let pages = 0;
    let looped = false;
    while (cursor !== null && pages < options.maxPages) {
        // 环检测独立于 maxPages：只靠页数兜底的话，
        // 调用方拿到的是「一百页重复数据 + truncated: true」，
        // 会以为后面还有更多
        if (visited.has(cursor)) {
            looped = true;
            break;
        }
        visited.add(cursor);
        const response = await request(cursor);
        pages += 1;
        const page = (response.data || {});
        // 服务端返回畸形数据时不要让整次遍历崩掉
        if (Array.isArray(page.items)) {
            // push 而不是重新构造数组：后者在页数多时是 O(n²) 次复制
            for (const item of page.items)
                items.push(item);
        }
        cursor = typeof page.next === 'string' ? page.next : null;
    }
    return {
        items,
        pages,
        // 还有下一页却停下来了，才算被截断
        truncated: cursor !== null && !looped,
        looped,
    };
}

